CREATE OR REPLACE FUNCTION public.community_friend_profile(p_target_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare me text:=public.pr_current_profile_id(); r jsonb; begin if not public.community_is_active_member(me) or not community_are_friends(me,p_target_id) or exists(select 1 from public.community_blocks b where (b.blocker_profile_id=me and b.blocked_profile_id=p_target_id) or (b.blocker_profile_id=p_target_id and b.blocked_profile_id=me)) then raise exception 'Este perfil es privado para tu círculo'; end if; select jsonb_build_object('id',p.id,'nombre',p.nombre,'apellido',p.apellido,'foto',p.foto,'banner',p.banner,'verificado',coalesce(p.verificado,false),'ciudad',case when coalesce(cp.show_city,true) then p.ciudad else null end,'sobre_mi',case when coalesce(cp.show_bio,true) then p.sobre_mi else null end,'instagram',case when coalesce(p.profile_privacy->>'show_socials','true')='true' then p.instagram end,'roller_status',p.roller_status,'profile_accent',p.profile_accent,'setup_patines',case when coalesce(p.profile_privacy->>'show_setup','true')='true' then p.setup_patines end,'showcase',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'slot_key',s.slot_key,'title',s.title,'subtitle',s.subtitle,'image_url',s.image_url,'sort_order',s.sort_order) order by s.sort_order,s.created_at desc),'[]'::jsonb) from pr_profile_showcase s where s.profile_id=p.id and (s.slot_key not in ('patines','ruedas','calle') or coalesce(p.profile_privacy->>'show_setup','true')='true')),'friend_count',case when coalesce(p.profile_privacy->>'show_friends','true')='true' then (select count(*) from community_friendships f where p.id in(f.profile_a_id,f.profile_b_id)) end,'social_badges',case when pr_social_internal.allowed() and coalesce(cp.show_badges_to_friends,true) then (select coalesce(jsonb_agg(jsonb_build_object('title',b.titulo,'date',b.fecha) order by b.fecha desc),'[]'::jsonb) from (select distinct on(titulo) titulo,fecha from public.actividad_pr where alumno_id=p.id and tipo='Insignia' and not eliminado order by titulo,fecha desc limit 100)b) else null end,'friend_since',case when pr_social_internal.allowed() then (select min(f.created_at) from public.community_friendships f where (f.profile_a_id=me and f.profile_b_id=p.id) or (f.profile_b_id=me and f.profile_a_id=p.id)) end,'shared_albums',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'owner_id',a.owner_id,'owner_name',op.nombre,'photo_count',(select count(*) from community_album_media am where am.album_id=a.id),'cover',case when pr_social_internal.allowed() then (select am.media_path from community_album_media am where am.album_id=a.id order by am.created_at limit 1) end) order by a.created_at desc),'[]'::jsonb) from community_albums a join profiles op on op.id=a.owner_id where (a.owner_id=p.id or exists(select 1 from community_album_members m where m.album_id=a.id and m.profile_id=p.id and m.status='accepted')) and (a.is_public or public.community_can_view_album(a.id,me))),'linked_posts',(select coalesce(jsonb_agg(jsonb_build_object('id',cpst.id,'body',cpst.body,'created_at',cpst.created_at,'author_id',cpst.author_id,'author_name',ap.nombre) order by cpst.created_at desc),'[]'::jsonb) from community_posts cpst join profiles ap on ap.id=cpst.author_id where cpst.deleted_at is null and (cpst.visibility='members' or public.community_are_friends(me,cpst.author_id)) and not exists(select 1 from public.community_blocks b where (b.blocker_profile_id=me and b.blocked_profile_id=cpst.author_id) or (b.blocker_profile_id=cpst.author_id and b.blocked_profile_id=me)) and (cpst.author_id=p.id or exists(select 1 from community_post_tags t where t.post_id=cpst.id and t.profile_id=p.id and t.status='accepted') or exists(select 1 from community_reposts rr where rr.post_id=cpst.id and rr.profile_id=p.id)))) into r from profiles p left join community_privacy cp on cp.profile_id=p.id where p.id=p_target_id and p.estado='Activo' and p.acceso_habilitado is true; return r; end $function$
;
CREATE OR REPLACE FUNCTION public.pr_social_profile(p_target text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pid text:=public.pr_current_profile_id(); target text:=coalesce(p_target,pid); 
begin
 if not pr_social_internal.allowed() or not public.community_are_friends(pid,target) or not exists(select 1 from public.profiles q where q.id=target and q.estado='Activo' and q.acceso_habilitado is true) or exists(select 1 from public.community_blocks b where (b.blocker_profile_id=pid and b.blocked_profile_id=target) or (b.blocker_profile_id=target and b.blocked_profile_id=pid)) then raise exception 'Perfil no disponible' using errcode='42501';end if;
 return jsonb_build_object('posts',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select p.id,p.body,p.created_at,p.author_id,coalesce((select pp.kind from pr_social_internal.prompt_posts pp where pp.post_id=p.id),case when exists(select 1 from pr_social_internal.polls q where q.post_id=p.id) then 'poll' when exists(select 1 from pr_social_internal.videos v where v.post_id=p.id) then 'video' else 'post' end) as social_kind,(p.author_id=target) as own,exists(select 1 from public.community_post_tags t where t.post_id=p.id and t.profile_id=target and t.status='accepted') as tagged,(select m.media_path from public.community_post_media m where m.post_id=p.id order by m.sort_order limit 1) as photo,(select v.object_path from pr_social_internal.videos v where v.post_id=p.id) as video_path from public.community_posts p where p.deleted_at is null and (p.visibility='members' or public.community_are_friends(pid,p.author_id)) and not exists(select 1 from public.community_blocks b where (b.blocker_profile_id=pid and b.blocked_profile_id=p.author_id) or (b.blocker_profile_id=p.author_id and b.blocked_profile_id=pid)) and (p.author_id=target or exists(select 1 from public.community_post_tags t where t.post_id=p.id and t.profile_id=target and t.status='accepted')) order by p.created_at desc limit 100)x),'[]'::jsonb),'friends',case when exists(select 1 from public.profiles q where q.id=target and coalesce(q.profile_privacy->>'show_friends','true')='true') or pid=target then (select count(*) from public.community_friendships f where target in (f.profile_a_id,f.profile_b_id)) end,'throwback',(select jsonb_build_object('id',p.id,'body',p.body,'created_at',p.created_at,'photo',(select m.media_path from public.community_post_media m where m.post_id=p.id order by m.sort_order limit 1)) from public.community_posts p where p.author_id=target and p.deleted_at is null and p.created_at<now()-interval '30 days' and (p.visibility='members' or public.community_are_friends(pid,p.author_id)) order by p.created_at desc limit 1));
end $function$
;
revoke all on function public.community_friend_profile(text) from public,anon;
grant execute on function public.community_friend_profile(text) to authenticated;
revoke all on function public.pr_social_profile(text) from public,anon;
grant execute on function public.pr_social_profile(text) to authenticated;